const FBS_REQUEST_LINK_MOVING = 'MOVING';
const FBS_REQUEST_LINK_REMOVED = 'REMOVED';
const FBS_REQUEST_LINK_RETURN_REQUIRED = 'RETURN_REQUIRED';
